#nullable enable // autogenerated  

using MVZ2.GameContent.Buffs.Enemies;
using MVZ2.GameContent.Contraptions;
using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using Tools;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.WickedHermitMannequin)]
    public class WickedHermitMannequin : AIEntityBehaviour
    {
        public WickedHermitMannequin(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            HealthLossSpawnHelper.Init(entity, ID);

            if (!entity.IsPreviewEnemy() && !entity.Level.IsIZombie())
            {
                var talisman = SpawnRandomMannequin(entity);
                SetTalismanZombie(entity, new EntityID(talisman));
            }
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            // 每损失 150 血，从内置池生成一个器械，最多 2 次    
            HealthLossSpawnHelper.CheckHealthLossTrigger(entity, ID, 150f, 2,
                e => HealthLossSpawnHelper.SpawnWeightedRandom(e, RandomEntity, RandomEntityWeights));
        }
        // 从 Mannequin 敌怪池中加权随机生成一个，并返回生成的实体  
        private Entity? SpawnRandomMannequin(Entity entity)
        {
            var index = entity.RNG.WeightedRandom(RandomMannequinWeights);
            var id = RandomMannequin[index];
            return entity.SpawnWithParams(id, entity.Position);
        }
        private static NamespaceID[] RandomMannequin = new NamespaceID[]
        {
            VanillaEnemyID.Mannequin,
            VanillaEnemyID.ImpMannequin,
            VanillaEnemyID.MegaImpMannequin,
            VanillaEnemyID.MannequinTNT,
            VanillaEnemyID.CannonballMannequin,
        };

        private static int[] RandomMannequinWeights = new int[]
        {
            10,
            10,
            5,
            20,
            20,
        };

        private static NamespaceID[] RandomEntity = new NamespaceID[]
        {
            VanillaContraptionID.teslaCoil,
            VanillaContraptionID.splitenser,
            VanillaContraptionID.beacon,
            VanillaContraptionID.silvenser,
            VanillaContraptionID.drivenser,
            VanillaContraptionID.dispenser,
            VanillaContraptionID.moonlightSensor,
        };

        private static int[] RandomEntityWeights = new int[]
        {
            2,
            10,
            3,
            10,
            10,
            10,
            1,
        };

        private static readonly NamespaceID ID = VanillaEnemyID.WickedHermitMannequin;
        protected override void UpdateAI(Entity enemy)
        {
            base.UpdateAI(enemy);
            if (!IsWarpped(enemy) && !enemy.IsDead)
            {
                var talismanID = GetTalismanZombie(enemy);
                var talisman = talismanID?.GetEntity(enemy.Level);
                if (!talisman.ExistsAndAlive() || !talisman.IsFriendly(enemy))
                {
                    SetTalismanZombie(enemy, null);
                    enemy.AddBuff<WickedHermitWarpBuff>();
                    SetWarpped(enemy, true);
                    enemy.PlaySound(VanillaSoundID.gapWarp);
                }
            }
        }
        public static void SetWarpped(Entity entity, bool value)
        {
            entity.SetBehaviourField(PROP_WARPPED, value);
        }
        public static bool IsWarpped(Entity entity)
        {
            return entity.GetBehaviourField<bool>(PROP_WARPPED);
        }
        public static void SetTalismanZombie(Entity entity, EntityID? value)
        {
            entity.SetBehaviourField(PROP_TALISMAN_ZOMBIE, value);
        }
        public static EntityID? GetTalismanZombie(Entity entity)
        {
            return entity.GetBehaviourField<EntityID>(PROP_TALISMAN_ZOMBIE);
        }

        public override void PostDeath(Entity entity, DeathInfo info)
        {
            base.PostDeath(entity, info);
            if (entity.WillRemoveOnDeath(info))
                return;
            SpawnRandomMannequin(entity);
        }

        public const int MOVE_INTERVAL = 30;
        public const float TALISMAN_DISTANCE = 80;
        public static readonly VanillaEntityPropertyMeta<bool> PROP_WARPPED = new VanillaEntityPropertyMeta<bool>("warpped");
        public static readonly VanillaEntityPropertyMeta<EntityID> PROP_TALISMAN_ZOMBIE = new VanillaEntityPropertyMeta<EntityID>("MoveTimer");
    }
}
